const rows = $input.all().map(item => item.json || {});
const metadataRow = rows.find(row => row.ContractVersion) || {};
const filters = rows
  .filter(field => Number(field.IsSystemParam || 0) !== 1 && field.FieldCode && field.FieldCode !== '@Invalid')
  .map(field => ({
    FieldCode: field.FieldCode,
    FieldName: field.FieldName,
    Placeholder: field.Placeholder,
    Required: Number(field.IsRequired || 0) === 1,
    IsRequired: Number(field.IsRequired || 0),
    DataType: field.DataType,
    ControlType: field.ControlType,
    DefaultValue: field.DefaultValue,
    ValidationRule: field.ValidationRule,
    SourceOfTruth: field.SourceOfTruth,
    OrderIndex: field.OrderIndex,
    DataSourceType: field.DataSourceType,
    DataSourceValue: field.DataSourceValue,
    UiTemplate: field.UiTemplate
  }));
return [{ json: {
  filters,
  contract: {
    version: metadataRow.ContractVersion || null,
    checksum: metadataRow.ContractChecksum || null,
    updatedAt: metadataRow.UpdatedAt || null,
    updatedBy: metadataRow.UpdatedBy || null
  }
} }];

const request = $('Check Method GetConfig').first().json;
const authResult = $('Execute Shared Auth Guard (GetConfig)').first().json;
const context = request._requestContext || authResult._requestContext || {};
const esc = (value, max) => String(value ?? '').replace(/'/g, "''").slice(0, max);
const hashOrNull = (value) => /^[a-f0-9]{64}$/i.test(String(value || '')) ? "'" + String(value).toLowerCase() + "'" : 'NULL';
const requestId = esc(context.requestId, 100);
if (!/^req-[A-Za-z0-9._:-]{4,96}$/.test(requestId)) throw new Error('AUDIT_REQUEST_ID_INVALID');
const apiCode = esc(request.body?.ApiCode, 100) || '@unknown';
const operationType = esc('CATALOG', 20) || 'UNKNOWN';
const resultCode = esc('OK', 60) || 'UNKNOWN';
const httpStatus = Number(200) || 500;
const count = Math.max(0, Number(($json.filters || []).length) || 0);
const rowCountBucket = count === 0 ? '0' : count === 1 ? '1' : count <= 10 ? '2-10' : count <= 100 ? '11-100' : '100+';
const durationMs = Math.max(0, Date.now() - Number(context.startedAtEpochMs || Date.now()));
const transactionOutcome = esc('NOT_APPLICABLE', 30) || 'NOT_APPLICABLE';
const startedAt = /^\d{4}-\d{2}-\d{2}T/.test(String(context.startedAtIso || '')) ? String(context.startedAtIso) : new Date().toISOString();
const query = `EXEC dbo.AI_WriteAPIRequestAudit
  @RequestID='${requestId}',
  @CorrelationHintHash=${hashOrNull(context.correlationHintHash)},
  @VerifiedUserHash=${hashOrNull(authResult.verifiedIdentity?.auditSubjectHash)},
  @ApiCode='${apiCode}',
  @OperationType='${operationType}',
  @ResultCode='${resultCode}',
  @HttpStatus=${httpStatus},
  @DurationMs=${durationMs},
  @RowCountBucket='${rowCountBucket}',
  @IdempotencyKeyHash=${hashOrNull(context.idempotencyKeyHash)},
  @TransactionOutcome='${transactionOutcome}',
  @N8nExecutionID='${esc(context.n8nExecutionId, 80)}',
  @StartedAt='${esc(startedAt, 30)}';`;
return [{ json: { query } }];

